/* Wait for the agent to create the evidence directory, then publish
 * one heartbeat before the FIFO can fill. Without this the stalled
 * run leaves no heartbeat at all, and "file missing" is weaker
 * evidence than "value never changed".
 */
{
    int tries;

    for (tries = 0; tries < 300; tries++) {
        FILE *probe = fopen(HEARTBEAT_PATH, "w");

        if (probe) {
            fprintf(probe, "0\n");
            fclose(probe);
            /* SiliconLoop: publish_identity() above ran before
             * ai_agent had mounted /data and created the evidence
             * directory, so that first attempt silently lost the
             * pid/mode files. The directory is usable now - republish
             * so recover_task L1/L2 has something to target. */
            publish_identity(argc > 1 ? argv[1] : "normal");
            break;
        }

        sleep(1);
    }
}

